/* ==========================================================================
   CHARTS SECTION (SVG & INTERACTIVE TOOLTIPS)
   ========================================================================== */
.charts-row {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 20px;
}

@media (max-width: 1024px) {
    .charts-row {
        grid-template-columns: 1fr;
    }
}

.chart-card {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 14px;
    padding: 25px;
    box-shadow: var(--card-shadow);
    display: flex;
    flex-direction: column;
    gap: 20px;
    position: relative;
}

.chart-card-header {
    display: flex;
